-- Wat is nieuw: meerwerk aanvinken en klaarzetten vanaf de Verkoop-tab.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-24','nieuw','Financieel','Meerwerk factureren vanaf de Verkoop-tab',
   'In het blok "Meerwerk in termijnstaat" vink je meerwerk aan en zet je het klaar als conceptfactuur in Bouw7, samen of per meerwerk apart. EVA kijkt eerst in Bouw7 wat al gefactureerd is; dat meerwerk is niet meer te kiezen, zodat niets dubbel op een factuur komt.');
